return { api_version=1, id="CS2_012", rarity = "free", name="Swipe", text="Deal $4 damage to an enemy and $1 damage to all other enemies.", set="LEGACY", type="spell", class="druid", cost=3, target_mode="required", targets=function(ctx,self) return ctx:enemy_characters(self) end, on_play=function(ctx,self,target) local hits={{target,4}}; for _,e in ipairs(ctx:enemy_characters(self)) do if e~=target then hits[#hits+1]={e,1} end end; cardlib.effects.damage_batch(ctx, hits) end }
